def _prepare_runtime() -> Path:
    payload = zlib.decompress(base64.b85decode("".join(_BUNDLE).encode("ascii")))
    digest = hashlib.sha256(payload).hexdigest()[:16]
    target = Path(tempfile.gettempdir()) / f"telegram-bot-runtime-{digest}"
    marker = target / ".ready"
    if not marker.exists():
        target.mkdir(parents=True, exist_ok=True)
        with zipfile.ZipFile(__import__("io").BytesIO(payload)) as archive:
            archive.extractall(target)
        marker.write_text(digest, encoding="ascii")
    return target

if __name__ == "__main__":
    runtime = _prepare_runtime()
    sys.path.insert(0, str(runtime))
    # Keep the project root as cwd so Render env files and persistent paths resolve normally.
    runpy.run_path(str(runtime / "bot.py"), run_name="__main__")
